    """Extend clear diagonal runs beyond matching-color diagonal pairs."""
    h, w = len(grid), len(grid[0])
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                r2, c2 = r + dr, c + dc
                if not (0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == color):
                    continue
                pair = (r, c, r2, c2)
                if pair in seen:
                    continue
                seen.add(pair)
                # Continue the same diagonal outward from each end, stopping at
                # the first non-background cell or the grid boundary.
                for rr, cc, sr, sc in ((r-dr, c-dc, -dr, -dc), (r2+dr, c2+dc, dr, dc)):
